#!/usr/bin/env python3
"""Fill symbol read-aloud gaps with existing ADT Studio voice recordings."""

from __future__ import annotations

import json
import shutil
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
I18N = ROOT / "content" / "i18n" / "en-GB"
AUDIO_DIR = I18N / "audio"
TEXTS_PATH = I18N / "texts.json"
AUDIOS_PATH = I18N / "audios.json"

# Reuse single-word glossary recordings generated by ADT Studio.
SOURCE_AUDIO = {
    "+": "gl003.mp3",   # “add”
    "=": "gl055.mp3",   # “equals”
    "×": "gl115.mp3",   # “multiply”
}


def main() -> None:
    texts = json.loads(TEXTS_PATH.read_text(encoding="utf-8"))
    audios = json.loads(AUDIOS_PATH.read_text(encoding="utf-8"))
    added = []

    for data_id, value in texts.items():
        if data_id in audios or value not in SOURCE_AUDIO:
            continue
        destination_name = f"{data_id}.mp3"
        shutil.copyfile(AUDIO_DIR / SOURCE_AUDIO[value], AUDIO_DIR / destination_name)
        audios[data_id] = destination_name
        added.append({"data_id": data_id, "spoken_as": SOURCE_AUDIO[value]})

    AUDIOS_PATH.write_text(
        json.dumps(audios, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )
    print(json.dumps({"added": len(added), "items": added}, indent=2))


if __name__ == "__main__":
    main()
